"""The catalogue, in a JSON file (SHELF_DB, default ./shelf.json).

Every access runs under an exclusive OS lock on the sidecar <db>.lock file,
so separate shelf processes never interleave a read-modify-write.
"""
import contextlib
import json
import os
import time

if os.name == "nt":
    import msvcrt
else:
    import fcntl

LOCK_TIMEOUT = 10.0


class ShelfError(Exception):
    pass


class NotFound(ShelfError):
    pass


class AlreadyLent(ShelfError):
    pass


class NotLent(ShelfError):
    pass


def _path():
    return os.environ.get("SHELF_DB", "shelf.json")


def _load():
    try:
        with open(_path(), encoding="utf-8") as f:
            return json.load(f)
    except FileNotFoundError:
        return {"books": [], "loans": {}}


def _save(data):
    db = _path()
    tmp = db + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        f.write(json.dumps(data, indent=2))
        f.flush()
        os.fsync(f.fileno())
    for attempt in range(50):
        try:
            os.replace(tmp, db)
            return
        except PermissionError:
            if attempt == 49:
                raise
            time.sleep(0.02)


def _try_lock(fd):
    if os.name == "nt":
        os.lseek(fd, 0, 0)
        msvcrt.locking(fd, msvcrt.LK_NBLCK, 1)
    else:
        fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)


def _unlock(fd):
    if os.name == "nt":
        os.lseek(fd, 0, 0)
        msvcrt.locking(fd, msvcrt.LK_UNLCK, 1)
    else:
        fcntl.flock(fd, fcntl.LOCK_UN)


@contextlib.contextmanager
def _locked():
    # The lock file is never deleted: removing it would let two processes
    # lock two different files.
    fd = os.open(_path() + ".lock", os.O_RDWR | os.O_CREAT, 0o666)
    try:
        deadline = time.monotonic() + LOCK_TIMEOUT
        while True:
            try:
                _try_lock(fd)
                break
            except OSError:
                if time.monotonic() >= deadline:
                    raise ShelfError("store is busy, try again")
                time.sleep(0.01)
        try:
            yield
        finally:
            _unlock(fd)
    finally:
        os.close(fd)


def _known(data, title):
    return any(b["title"] == title for b in data["books"])


def add(title, author):
    book = {"title": title, "author": author}
    with _locked():
        data = _load()
        data["books"].append(book)
        _save(data)
    return book


def find(query):
    with _locked():
        data = _load()
    return [b for b in data["books"] if query in b["title"]]


def all_books():
    with _locked():
        return list(_load()["books"])


def clear():
    with _locked():
        _save({"books": [], "loans": {}})


def lend(title, member):
    with _locked():
        data = _load()
        if not _known(data, title):
            raise NotFound("no such book: %s" % title)
        if title in data["loans"]:
            raise AlreadyLent("%s is already lent to %s" % (title, data["loans"][title]))
        data["loans"][title] = member
        _save(data)


def return_book(title):
    with _locked():
        data = _load()
        if not _known(data, title):
            raise NotFound("no such book: %s" % title)
        if title not in data["loans"]:
            raise NotLent("%s is not lent" % title)
        del data["loans"][title]
        _save(data)


def holder(title):
    with _locked():
        return _load()["loans"].get(title)

